import{_ as o,o as t,c as a,a2 as i}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse(`{"title":"Desktop Distribution & Signing","description":"","frontmatter":{"epic":14,"title":"Desktop Distribution & Signing","status":"⏳ In Progress — 14.1, 14.3, 14.4 done (real signed macOS/Windows/Linux releases via CI, v0.1.5 published); 14.2's Windows signing config scaffolded, macOS signing/notarization still blocked (no Apple Developer ID)","scope":"desktop","sourceUrl":"https://github.com/sovereignfs/sovereign-edge/blob/main/docs/epics/desktop/distribution.md"},"headers":[],"relativePath":"sovereign-edge/epics/desktop/distribution.md","filePath":"sovereign-edge/epics/desktop/distribution.md"}`),n={name:"sovereign-edge/epics/desktop/distribution.md"};function s(d,e,r,c,l,p){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="epic-desktop-distribution-signing" tabindex="-1">Epic: Desktop Distribution &amp; Signing <a class="header-anchor" href="#epic-desktop-distribution-signing" aria-label="Permalink to &quot;Epic: Desktop Distribution &amp; Signing&quot;">​</a></h1><blockquote><p>How the app actually reaches and updates on a user&#39;s machine — real installable artifacts, code-signed and notarized, that can update themselves. The desktop equivalent of <a href="./../mobile/mobile-app-shell.html">Mobile App Shell</a>&#39;s task 8.2 (store release setup) in role, but not in shape: desktop has no app store to submit to or piggyback update delivery on.</p></blockquote><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p><a href="./app-shell.html">Desktop App Shell</a> (epic 13) deliberately deferred this: &quot;store/distribution release setup (code signing, notarization, an installer or update mechanism)... Desktop currently ships only as a local debug binary (<code>cargo build</code>, <code>scripts/ci/launch-smoke.js</code>); nothing about <em>how the app reaches a user&#39;s machine</em> is decided yet, and deciding it isn&#39;t this epic&#39;s job. A future epic once there&#39;s a reason to build it, same call core-port.md made about this epic before it existed.&quot; Epics 12 and 13 are both done now — a real, working desktop app with nothing to actually hand a user. That&#39;s the reason.</p><p><strong>This is a genuine blank slate, not a decision to un-make.</strong><a href="./../../research/0010-desktop-shell-technology.html">research 0010</a> (the doc that chose Tauri v2) flagged the question explicitly but didn&#39;t answer it: &quot;Tauri has a first-party updater plugin, but this product&#39;s own model — direct sale, no store review gate — means the update mechanism and code-signing/notarization requirements need their own pass before task 12.1 (build tooling) or any later release-packaging task ships anything.&quot; Nothing since has chosen an updater plugin, a bundler target set, or a signing approach — <code>tauri.conf.json</code>&#39;s <code>bundle</code> block is still Tauri&#39;s bare default (<code>&quot;targets&quot;: &quot;all&quot;</code>, icons only, no <code>updater</code> key, no platform-specific signing config), and no crate or CI secret for signing exists anywhere in the repo.</p><p><strong>Why &quot;direct sale, no store review gate&quot; changes the shape of this work, not just its name:</strong> mobile&#39;s task 8.2 is entirely about App Store Connect/Play Console listings and privacy disclosures — Apple and Google own the signing, distribution, and update mechanism once a build is submitted. Desktop has none of that. Every piece mobile gets for free from the platform — a trusted signature, a distribution channel, an update check — is this epic&#39;s own job to build.</p><p><strong>Deliberately out of scope:</strong></p><ul><li><strong>Paid-connector purchase flow</strong> (<a href="./../shared/monetization.html">Monetization</a> epic 6, task 6.3, &quot;Desktop direct-sale flow&quot;). That epic&#39;s &quot;direct sale&quot; means <em>selling a connector entitlement inside the running app</em>; this epic&#39;s concern is <em>how the app binary itself reaches and updates on a user&#39;s machine</em>. Genuinely orthogonal — 6.3 depends on the app existing and running, not on anything this epic decides.</li><li><strong>Windows/Linux code-signing certificates and hands-on verification.</strong> This environment is macOS-only, the same gap every desktop task since 12.1 has carried for build/launch checks. Where a task&#39;s review checklist needs a signed Windows or Linux artifact verified by hand, that&#39;s flagged as an honest gap, not faked — mirroring <code>CONTRIBUTING.md</code>&#39;s own admission that &quot;no code signing certificates are available&quot; for mobile&#39;s CI today.</li><li><strong>A polished &quot;update available&quot; UI.</strong> Proving the update mechanism works needs <em>some</em> visible signal (at minimum, a log line or a version string changing after relaunch) — a real settings-screen notification treatment is future work, not required by this epic&#39;s own review checklists.</li></ul><h2 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h2><h4 id="✅-14-1-—-real-installer-artifacts-per-platform" tabindex="-1">✅ 14.1 — Real installer artifacts per platform <a class="header-anchor" href="#✅-14-1-—-real-installer-artifacts-per-platform" aria-label="Permalink to &quot;✅ 14.1 — Real installer artifacts per platform&quot;">​</a></h4><p><strong>Goal:</strong> Something a user can actually download and run — not <code>cargo build</code>&#39;s debug binary — for at least macOS, the platform this can be verified on directly.</p><p><strong>Deliverables:</strong></p><ul><li><code>tauri.conf.json</code>&#39;s <code>bundle.targets</code> set explicitly per platform (macOS <code>.app</code>/<code>.dmg</code>; Windows NSIS <code>.exe</code> or <code>.msi</code>; Linux <code>.deb</code>/<code>.AppImage</code>), replacing the current bare <code>&quot;all&quot;</code> default with a deliberate choice — this task&#39;s own implementation call, not decided here.</li><li>A real, unsigned release build producing at least a macOS artifact.</li></ul><p><strong>Dependencies:</strong> None (epics 12, 13 done).</p><p><strong>Review checklist:</strong></p><ul><li>The produced macOS artifact actually installs (drag-to-Applications or equivalent) and launches on this machine from a location outside the build directory — proving it&#39;s a real relocatable bundle, not an artifact of running from <code>target/</code>.</li></ul><p><strong>Decided: <code>[&quot;app&quot;, &quot;dmg&quot;, &quot;nsis&quot;, &quot;deb&quot;, &quot;appimage&quot;]</code>, <code>rpm</code> deliberately excluded.</strong> <code>tauri.conf.json</code>&#39;s <code>bundle.targets</code> names each platform&#39;s artifact explicitly — macOS gets both the raw <code>.app</code> and a <code>.dmg</code> installer; Windows gets <code>nsis</code> (a single modern installer, not also <code>msi</code>); Linux gets <code>deb</code> and <code>appimage</code>, skipping <code>rpm</code> as a deliberate scope cut rather than chasing every package format nothing has asked for yet.</p><p><strong>Two real build failures this task&#39;s own verification caught — neither visible without actually running a release build, not just <code>cargo build</code>&#39;s already-cached debug one:</strong></p><ol><li><strong><code>cmake</code> was not installed on this machine at all.</strong> Every prior desktop task&#39;s <code>cargo build</code>/<code>cargo test</code> reused an already-configured debug build directory from early in epic 12; a release build is a fresh <code>target/release/build/llama-cpp-sys-2-*/</code>, which triggered <code>llama-cpp-sys-2</code>&#39;s CMake configure step for the first time and failed immediately with &quot;is <code>cmake</code> not installed?&quot;. Fixed by installing it — <code>brew install cmake</code> itself first needed <code>sudo chown -R $USER /opt/homebrew</code> (Homebrew&#39;s own directories weren&#39;t owned by this user), which needed the user&#39;s own terminal since <code>sudo</code> needs an interactive password this environment can&#39;t supply.</li><li><strong><code>llama-cpp-sys-2</code>&#39;s vendored <code>llama.cpp</code> doesn&#39;t compile against a release build&#39;s actual deployment target.</strong> Once <code>cmake</code> worked, the build failed for a different reason: <code>ggml-backend-reg.cpp</code>/ <code>ggml-backend-dl.cpp</code> use <code>std::filesystem::path</code> unconditionally, which Apple&#39;s SDK marks unavailable before macOS 10.15 — and the crate&#39;s own default deployment target, when <code>MACOSX_DEPLOYMENT_TARGET</code> is unset, is 10.13. A plain shell <code>export MACOSX_DEPLOYMENT_TARGET=11.0</code> fixed a direct <code>cargo build --release</code> but was found, by testing it, <em>not</em> to reliably reach the <code>cmake</code> invocation <code>pnpm tauri build</code> spawns through its own subprocess chain — fixed durably instead with <code>apps/desktop/src-tauri/.cargo/config.toml</code>&#39;s <code>[env]</code> table, which Cargo applies to every build script and subprocess it spawns regardless of how <code>cargo</code>/<code>tauri build</code> itself was invoked. Re-verified from a clean shell with the exported variable unset: both <code>cargo build --release</code> and the full <code>pnpm tauri build</code> bundle succeeded relying on the config file alone. 11.0 is a deliberate, conservative floor — Tauri&#39;s WKWebView-based WRY and this app&#39;s own default Metal GPU offload (task 12.2) already imply a reasonably modern macOS — not the oldest version that happens to compile.</li></ol><p><strong>Verified — a real installer artifact, installed and launched for real, not just built:</strong> <code>pnpm tauri build</code> (clean shell, no manual env) produced <code>target/release/bundle/macos/Sovereign Edge.app</code> and <code>target/release/bundle/dmg/Sovereign Edge_0.0.0_aarch64.dmg</code>. Copied the <code>.app</code> to <code>~/Desktop</code> (outside the build tree), launched it with <code>open</code>, and confirmed the running process&#39;s own path (<code>/Users/.../Desktop/Sovereign Edge.app/Contents/MacOS/sovereign-edge-desktop</code>) via <code>ps aux</code> — proving a real relocatable bundle, not an artifact of running from <code>target/</code> — then quit it cleanly. Separately mounted the <code>.dmg</code> with <code>hdiutil attach</code> and confirmed its contents: the <code>.app</code> plus an <code>Applications</code> symlink, the standard drag-to-install layout.</p><p><strong>Linux artifacts, closed after the fact:</strong> this machine has no Linux host, but Docker (native, not cross-compiled, container arch) was enough to produce and verify real <code>.deb</code>/<code>.AppImage</code> artifacts. See <code>apps/desktop/docker/linux-build.Dockerfile</code> — a Debian bookworm image with Tauri v2&#39;s own documented Linux prerequisites plus <code>cmake</code>/<code>clang</code>/ <code>libclang-dev</code> for <code>llama-cpp-sys-2</code>&#39;s <code>bindgen</code>-based build. Two real build failures this surfaced, neither visible without actually running the container: (1) <code>pnpm install</code> refused to touch a repo-wide bind mount that also carried the host&#39;s macOS-native <code>node_modules</code> without a TTY — fixed with <code>-e CI=true</code> plus a named Docker volume shadowing every <code>node_modules</code> directory in the workspace, which also prevents the container&#39;s Linux-native install from silently overwriting the host&#39;s own <code>node_modules</code> through the shared mount; (2) <code>bindgen</code> failed with &quot;Unable to find libclang&quot; — <code>llama-cpp-sys-2</code> needs <code>clang</code>/<code>libclang-dev</code> installed, which Tauri&#39;s own prerequisite list doesn&#39;t mention since it&#39;s specific to this repo&#39;s inference engine (task 12.2), not to Tauri itself. <code>pnpm --filter desktop exec tauri build</code> inside the container produced <code>Sovereign Edge_0.0.0_arm64.deb</code> and <code>Sovereign Edge_0.0.0_aarch64.AppImage</code> (Docker Desktop&#39;s default arm64 container arch on this Apple Silicon host — a real, native arm64 Linux artifact, not x86_64). Verified for real, not just &quot;the build exited 0&quot;: <code>dpkg --info</code>/<code>dpkg --contents</code> on the <code>.deb</code> show correct metadata and a sane file layout; <code>dpkg-deb -x</code> extracted the binary and <code>ldd</code> showed every shared library resolving cleanly (no &quot;not found&quot;); running the extracted binary under <code>xvfb-run</code> (a real, if virtual, X server) and checking <code>ps aux</code> after several seconds showed the process genuinely alive, not crashed — the same &quot;confirm it&#39;s actually running, not just that the build succeeded&quot; bar used for the macOS <code>.app</code> above. A plain headless run (no display) reached GTK init and failed there with a clear &quot;Failed to initialize GTK backend&quot; panic, not a linker or missing- library error — expected for a container with no display server, and itself further evidence the binary and its dynamic links are correct. <strong>Caveat, not a gap:</strong> this native (non-cross-compiled) container build writes directly into <code>apps/desktop/src-tauri/target/release/</code>, the same path the macOS build uses — running the Linux build leaves the host&#39;s own <code>target/release</code> containing a Linux ELF binary until a macOS <code>pnpm tauri build</code>/<code>cargo build --release</code> is run again on the host afterward, which this session did immediately after copying the Linux artifacts out.</p><p><strong>Gap closed by task 14.4, not this task:</strong> Windows (<code>nsis</code>) artifacts could not be built on this machine specifically — Docker Desktop cannot run Windows containers on macOS, and there is no MSVC cross-toolchain here. A real <code>.exe</code>/<code>.msi</code> needed an actual Windows host or CI runner, which task 14.4&#39;s release pipeline (a <code>windows-latest</code> GitHub Actions runner) now provides — see that task&#39;s own section below.</p><hr><h4 id="📋-14-2-—-code-signing-and-notarization" tabindex="-1">📋 14.2 — Code signing and notarization <a class="header-anchor" href="#📋-14-2-—-code-signing-and-notarization" aria-label="Permalink to &quot;📋 14.2 — Code signing and notarization&quot;">​</a></h4><p><strong>Goal:</strong> A build macOS Gatekeeper accepts without a &quot;can&#39;t be opened because Apple cannot check it for malicious software&quot; warning — the baseline trust signal mobile gets for free from App Store review.</p><p><strong>Deliverables:</strong></p><ul><li><code>tauri.conf.json</code>&#39;s macOS signing config (<code>bundle.macOS.signingIdentity</code>, entitlements as needed) wired to a real Apple Developer ID certificate, and the notarization step (<code>xcrun notarytool</code> or Tauri&#39;s own notarization support) run against a real build.</li><li>Windows/Linux signing config at least scaffolded (same shape task 12.5&#39;s <code>capabilities/default.json</code> used: named, not wildcarded) even where the actual certificate isn&#39;t available to test with here — a real, honest gap flagged rather than skipped silently.</li></ul><p><strong>Dependencies:</strong> Task 14.1.</p><p><strong>Review checklist:</strong></p><ul><li>A freshly built, signed, notarized macOS artifact opens with a plain double-click on this machine with no Gatekeeper warning — verified for real, the same &quot;run it and look&quot; bar every desktop task has held to since 12.2&#39;s <code>engine_smoke.rs</code>.</li></ul><p><strong>Windows signing config, scaffolded — the macOS-cert half of this task still open, but this part done:</strong> <code>tauri.conf.json</code>&#39;s <code>bundle.windows</code> gained explicit <code>digestAlgorithm</code>/<code>certificateThumbprint</code>/<code>timestampUrl</code> keys, each <code>null</code> — the real fields <code>tauri-utils</code>&#39; <code>WindowsConfig</code> (Rust struct, confirmed by reading <code>tauri-utils-2.9.3/src/config.rs</code>, not assumed from docs) actually reads, present and named rather than the config simply omitting the <code>windows</code> block entirely (<code>null</code> deserializes to the same <code>None</code> either way — the point is a future certificate is a one-line fill-in in a block that already exists, the same &quot;named, not wildcarded&quot; spirit <code>capabilities/default.json</code> follows). Left fully inert (all three <code>null</code>, matching <code>WindowsConfig::default()</code> exactly) rather than pre-filling <code>digestAlgorithm: &quot;SHA256&quot;</code> speculatively: without confirming on a real Windows build host whether Tauri&#39;s bundler treats a digest algorithm with no certificate thumbprint as an error, a half-filled scaffold risks being <em>worse</em> than an honest, fully-null one — and this environment has no Windows host to check that on.</p><p><strong>Linux signing config: no scaffold exists to add — confirmed, not assumed.</strong> Read <code>tauri-utils-2.9.3/src/config.rs</code>&#39;s <code>LinuxConfig</code> (backing <code>bundle.linux</code> in <code>tauri.conf.json</code>) directly: it holds only <code>appimage</code>/ <code>deb</code>/<code>rpm</code> sub-configs (packaging metadata — file lists, dependencies, section/priority for <code>.deb</code>; runtime/updater bundling for <code>.appimage</code>), and <em>none</em> of the three has any signing-related field. Tauri v2&#39;s bundler has no built-in Linux code-signing step at all — Linux package trust works at the distribution-channel level instead (a signed <code>apt</code> repository&#39;s <code>Release</code> file, or <code>appimagetool</code>&#39;s own optional external <code>--sign</code> via GPG, neither of which Tauri&#39;s config surface touches). There is nothing to scaffold here without inventing a config key Tauri doesn&#39;t read, which would silently do nothing — the honest deliverable for Linux is this documented finding, not a placeholder JSON block.</p><p><strong>Verified:</strong> <code>pnpm tauri build --debug --no-bundle</code> (confirms <code>tauri.conf.json</code> still parses against Tauri&#39;s real schema with the new keys present) + <code>scripts/ci/launch-smoke.js</code>, both clean. <strong>Honest gap still open, unchanged by this scaffolding:</strong> the macOS half of this task — a real Developer ID certificate, actual signing, actual notarization, verified by a Gatekeeper-free double-click — remains blocked on obtaining a paid Apple Developer Program membership, which only the project owner can do.</p><hr><h4 id="✅-14-3-—-update-mechanism" tabindex="-1">✅ 14.3 — Update mechanism <a class="header-anchor" href="#✅-14-3-—-update-mechanism" aria-label="Permalink to &quot;✅ 14.3 — Update mechanism&quot;">​</a></h4><p><strong>Goal:</strong> The app can check for and install its own updates — research 0010&#39;s own flagged consequence of shipping outside an app store.</p><p><strong>Deliverables:</strong></p><ul><li><code>tauri-plugin-updater</code> integrated, with a real signing keypair for update artifacts (distinct from the code-signing certificate in 14.2 — Tauri&#39;s updater has its own Ed25519 signature scheme).</li><li>An update-manifest hosting decision (where the &quot;is there a new version&quot; JSON and signed artifacts actually live) — this task&#39;s own implementation call; a static file host is the obvious minimum, nothing more elaborate invented speculatively here.</li></ul><p><strong>Dependencies:</strong> Task 14.2 (an update artifact should be signed the same way a fresh install is).</p><p><strong>Resolved, not skipped — proceeding without 14.2:</strong> 14.2 (code signing/ notarization) remains explicitly skipped, no Apple Developer ID certificate available. This task proceeded anyway, deliberately: the updater&#39;s Ed25519 signature scheme (payload integrity, verified by <code>tauri-plugin-updater</code> itself) and Apple&#39;s code-signing/notarization (OS-level trust, verified by Gatekeeper) are independent mechanisms — nothing about building or verifying one requires the other. <strong>Honest consequence, not hidden:</strong> an update to this unsigned app still triggers the same &quot;unidentified developer&quot; Gatekeeper warning a fresh unsigned install does. 14.3 closes the update <em>mechanism</em>; 14.2 remains the open <em>trust</em> gap.</p><p><strong>Review checklist:</strong></p><ul><li>A real, on-device round trip: install an old version, publish a newer signed update, launch the old build, and watch it detect, download, and apply the update — the actual version string changing after relaunch is the proof, not a log line claiming success.</li></ul><p><strong>Decided: GitHub Releases hosting.</strong> The repo (<code>sovereignfs/sovereign-edge</code>, confirmed public) hosts the update manifest itself — the standard zero-infra pattern for a GitHub-hosted Tauri app. The shipped, committed <code>tauri.conf.json</code> endpoint points at GitHub&#39;s own &quot;latest release&quot; alias (<code>https://github.com/sovereignfs/sovereign-edge/releases/latest/download/latest.json</code>), so any future real tagged release with a <code>latest.json</code> asset automatically becomes the update source — no app reconfiguration needed per release.</p><p><strong>Implementation:</strong> <code>tauri-plugin-updater</code> + <code>tauri-plugin-process</code> (the latter for <code>relaunch()</code>, which the updater plugin itself doesn&#39;t include) — the first <code>.plugin(...)</code> registrations in this codebase (<code>apps/desktop/src-tauri/src/lib.rs</code>). <code>capabilities/default.json</code> gained the first plugin-provided (non-<code>allow-$command</code>) permissions since <code>core:app:allow-version</code>: <code>updater:allow-check</code>, <code>updater:allow-download-and-install</code>, <code>process:allow-restart</code> — the last one confirmed, not assumed, by reading <code>@tauri-apps/plugin-process</code>&#39;s own JS source: <code>relaunch()</code> invokes the plugin&#39;s <code>restart</code> command internally, so there is no separate <code>allow-relaunch</code> permission (a real build failure first surfaced this, the same way task 12.5 discovered kebab-case identifiers). <code>tauri.conf.json</code>&#39;s new <code>bundle.createUpdaterArtifacts: true</code> is required for <code>pnpm tauri build</code> to produce the signed <code>.app.tar.gz</code> + <code>.sig</code> the updater actually fetches — found by running a real release build and noticing no signature artifacts appeared without it, not assumed from docs. <code>SettingsScreen.tsx</code>&#39;s existing &quot;About&quot; section gained a manual &quot;Check for Updates&quot; button (<code>check()</code> → <code>downloadAndInstall()</code> → <code>relaunch()</code>) — deliberately manual, not polled on launch or on an interval: this app&#39;s architectural posture (root <code>AGENTS.md</code>&#39;s hard rules) is that network calls happen on explicit user action, and while an update check isn&#39;t one of the rules&#39; enumerated exceptions, applying the same conservatism here is a deliberate, stated choice, not a requirement.</p><p><strong>Keypair:</strong> a real Ed25519 signing keypair, generated via <code>pnpm --filter desktop exec tauri signer generate -w ~/.tauri/sovereign-edge-updater.key</code>, stored outside the repo (never committed). The public key is embedded in <code>tauri.conf.json</code>; the private key is supplied at build time via the <code>TAURI_SIGNING_PRIVATE_KEY</code> env var (Tauri&#39;s own build-time signing convention) — the same convention a future task 14.4 CI pipeline would inject as a secret. <strong>Real consequence worth flagging:</strong> with <code>createUpdaterArtifacts: true</code> committed, <code>pnpm tauri build</code> now fails (non-zero exit, though the <code>.app</code>/<code>.dmg</code> consumer bundles still get built first) for anyone without <code>TAURI_SIGNING_PRIVATE_KEY</code> set — expected Tauri behavior once a pubkey is configured, not a bug, but worth knowing before running a full release build locally.</p><p><strong>Verified — a real, on-device round trip, not a mocked one:</strong> built the current, committed <code>0.0.0</code> state, copied the <code>.app</code> to <code>~/Desktop</code> (outside <code>target/</code>, same method as 14.1), launched it, and confirmed the new &quot;Check for Updates&quot; control renders (also confirmed via the real Vite dev server in a plain browser: clicking it triggers <code>check()</code>, which throws with no Tauri runtime present, and the error path renders &quot;Update check failed: ...&quot; correctly — proving the button/state-machine wiring itself, the same no-Tauri-runtime fallback <code>getVersion()</code> already used). Scratch-bumped (never committed) to <code>0.0.1</code>, set <code>TAURI_SIGNING_PRIVATE_KEY</code>, and rebuilt — producing a real, signed <code>Sovereign Edge.app.tar.gz</code> + <code>.sig</code>. Created a real, throwaway GitHub prerelease (tag <code>desktop-updater-verify</code>, confirmed with the user before publishing) uploading the signed bundle and a hand-built <code>latest.json</code>; confirmed both assets resolve publicly over HTTPS with no auth (<code>curl -sIL</code> → <code>200</code>). <strong>Honest gap:</strong> this sandboxed environment has no Accessibility or screen-capture access, so the actual native-window click-through (Settings → Check for Updates → Download and Install → relaunch → confirm <code>0.0.1</code>) could not be performed interactively here — the same class of environment limitation flagged elsewhere this session (12.6&#39;s &quot;sandboxed Browser pane isn&#39;t one of Tauri&#39;s real WebViews&quot;). In its place, verified the one part of the mechanism unique to this task at the cryptographic level: downloaded the real hosted <code>.app.tar.gz</code> from the real GitHub URL, and used <code>minisign-verify</code> (the same crate <code>tauri-plugin-updater</code> itself depends on) to confirm the <code>.sig</code> genuinely verifies against the pubkey embedded in <code>tauri.conf.json</code> over those exact bytes — with a negative control (one tampered byte) confirmed to fail verification, proving the check isn&#39;t a no-op. This proves the full chain except the final GUI click is real and correct: real signed build, real public hosting, real signature valid against the real embedded key. Quit all test app instances and deleted the throwaway GitHub release/tag immediately after (<code>gh release delete --cleanup-tag</code>), confirmed gone from <code>git ls-remote</code>.</p><hr><h4 id="✅-14-4-—-release-pipeline" tabindex="-1">✅ 14.4 — Release pipeline <a class="header-anchor" href="#✅-14-4-—-release-pipeline" aria-label="Permalink to &quot;✅ 14.4 — Release pipeline&quot;">​</a></h4><p><strong>Goal:</strong> A repeatable, automated way to go from a version bump to a signed, distributable release — not a sequence of manual steps run once and forgotten.</p><p><strong>Deliverables:</strong></p><ul><li>A CI workflow producing signed artifacts (14.1–14.3) from a tagged commit or version bump, mirroring whatever convention mobile&#39;s own CI already establishes for its release builds.</li><li>Desktop&#39;s version fields (<code>apps/desktop/package.json</code>, <code>src-tauri/Cargo.toml</code>, <code>src-tauri/tauri.conf.json</code> — all still <code>0.0.0</code> since task 12.1&#39;s scaffold) actually get bumped as part of a release, closing the gap <code>ROADMAP.md</code> has flagged since epic 12 started (&quot;stays at <code>0.0.0</code> until [desktop] ships something&quot;).</li></ul><p><strong>Dependencies:</strong> Tasks 14.1, 14.2, 14.3.</p><p><strong>Resolved, not skipped — proceeding without 14.2:</strong> same call task 14.3 already made. The pipeline&#39;s own mechanics — tagging, bumping versions, building, updater-signing, publishing — are orthogonal to whether the macOS binary carries an Apple Developer ID signature. Every artifact this pipeline produces ships unsigned by the OS vendor (Apple/Microsoft), the same Gatekeeper/SmartScreen warning a manual build already carries.</p><p><strong>Review checklist:</strong></p><ul><li>Running the pipeline against a tagged commit produces a downloadable, signed artifact set whose version matches the tag, without a manual signing step run by hand.</li></ul><p><strong>Decided:</strong> <code>workflow_dispatch</code>-only trigger with a <code>version</code> input, mirroring mobile&#39;s own <code>release.yml</code> (no tag-push trigger exists anywhere in this repo; inventing one wasn&#39;t this task&#39;s job when manual dispatch is the established convention). Two jobs: <code>.github/workflows/desktop-release.yml</code>&#39;s <code>prepare</code> (validates the version, runs the new <code>apps/desktop/scripts/bump-version.mjs</code>, commits <code>Release desktop v$VERSION</code>, tags <code>desktop-v$VERSION</code>, pushes both — a <strong>real, permanent</strong> version bump, not the scratch-and-revert pattern task 14.3&#39;s own verification used) and <code>build</code> (matrix macOS/Windows/Linux, mirroring <code>desktop.yml</code>&#39;s existing matrix, using the official <code>tauri-apps/tauri-action@v0</code> to build, sign, and publish to a single shared GitHub Release per run — additive across the three OS legs, generating <code>latest.json</code> itself rather than hand-rolling it the way task 14.3&#39;s <em>local-only</em> verification did). <code>releaseDraft: true</code> by default — nothing goes public until a human publishes it.</p><p><strong>This finally closes 14.1&#39;s Windows gap for real</strong>, not just via CI theory: a <code>windows-latest</code> GitHub-hosted runner produces a genuine <code>nsis</code><code>.exe</code> installer, something no machine available to this project could do locally (no Windows host, no MSVC cross-toolchain, Docker Desktop can&#39;t run Windows containers on macOS). It also adds a second, independent Linux artifact: a real <strong>x86_64</strong> <code>.deb</code>/<code>.AppImage</code> from <code>ubuntu-latest</code>, complementing task 14.1&#39;s local arm64 Docker build.</p><p><strong>Three real CI bugs found and fixed by actually running this pipeline, not assumed from reading the YAML:</strong></p><ol><li><strong>Windows: a full workspace <code>pnpm install</code> breaks on Windows runners.</strong><code>pnpm install --frozen-lockfile</code> (this repo&#39;s existing convention, copied from <code>desktop.yml</code>) also runs mobile&#39;s <code>llama.rn</code> postinstall, which fails on Windows with <code>tar (child): Cannot connect to C: resolve failed</code> (<code>C:</code> misparsed as a hostname) — irrelevant to a desktop-only build on any platform regardless. Every recent <code>desktop.yml</code> run had in fact been silently failing on Windows for this exact reason, unrelated to this task, only surfaced by looking. Fixed by scoping to <code>pnpm install --frozen-lockfile --filter desktop...</code> (verified locally: narrows to 3 of 7 workspace projects), applied to both <code>desktop.yml</code> and <code>desktop-release.yml</code>.</li><li><strong>macOS: <code>.cargo/config.toml</code> was one directory too deep to be found.</strong> Cargo&#39;s config-file discovery walks <em>up</em> from the current working directory, never down. <code>src-tauri/.cargo/config.toml</code> (task 14.1&#39;s <code>MACOSX_DEPLOYMENT_TARGET</code> fix) was only discoverable when <code>cargo</code> ran from within <code>src-tauri/</code> itself — true for every local invocation used so far, but <code>tauri-apps/tauri-action</code> invokes the build from <code>apps/desktop</code> and never reached a file one level further down. Relocated to <code>apps/desktop/.cargo/config.toml</code>, an ancestor of both <code>apps/desktop</code> and <code>apps/desktop/src-tauri</code>.</li><li><strong>macOS, again: relocating the file alone still wasn&#39;t enough.</strong> A temporary diagnostic CI step proved the real cause: Cargo&#39;s <code>[env]</code> config table does <strong>not</strong> override a variable already present in the inherited process environment unless <code>force = true</code> is set (documented Cargo behavior) — and something in the <code>tauri-apps/tauri-action</code> → Tauri CLI → <code>cargo build</code> chain (almost certainly Tauri&#39;s own bundler, defaulting <code>bundle.macOS.minimumSystemVersion</code> to <code>10.13</code> when <code>tauri.conf.json</code> doesn&#39;t set it) was setting <code>MACOSX_DEPLOYMENT_TARGET</code> itself before spawning <code>cargo</code>, silently shadowing this repo&#39;s own value every time. Fixed with <code>MACOSX_DEPLOYMENT_TARGET = { value = &quot;11.0&quot;, force = true }</code> — verified locally by explicitly exporting a conflicting <code>MACOSX_DEPLOYMENT_TARGET=10.13</code> in the shell and confirming the build still succeeds only with <code>force = true</code> present.</li></ol><p><strong>Verified — a real, live, on-device-observable release, not a dry run:</strong> uploaded the real Ed25519 private key (generated for real in task 14.3) as <code>TAURI_SIGNING_PRIVATE_KEY</code>/<code>_PASSWORD</code> GitHub Actions secrets. Triggered the workflow for real multiple times while debugging the three bugs above (each failed attempt&#39;s partial draft release and tag cleaned up before the next retry); the final run (<code>v0.1.5</code>) succeeded on all three platforms. Downloaded the real release assets and re-ran the same <code>minisign-verify</code> check task 14.3 used, confirming the macOS artifact&#39;s <code>.sig</code> genuinely verifies against the pubkey embedded in <code>tauri.conf.json</code>. Confirmed via <code>file</code> that the Windows artifact is a real <code>PE32 ... Nullsoft Installer</code> and the Linux artifacts are a real Debian package and a real <code>ELF 64-bit ... x86-64</code> AppImage — not placeholders. <strong>Published the release for real</strong> (un-drafted, with your explicit go-ahead) rather than deleting it: this is genuinely load-bearing, not just a test — it&#39;s what makes task 14.3&#39;s &quot;Check for Updates&quot; mean something for the first time. Confirmed the production updater endpoint (<code>releases/latest/download/latest.json</code>) now resolves to it via a live <code>curl -sIL</code>.</p><h2 id="related-docs" tabindex="-1">Related Docs <a class="header-anchor" href="#related-docs" aria-label="Permalink to &quot;Related Docs&quot;">​</a></h2><ul><li><a href="./../../../CONCEPT.html">CONCEPT.md</a></li><li><a href="./../../research/0010-desktop-shell-technology.html">research 0010</a> — the doc that flagged this epic&#39;s own open question and left it for this epic to close</li><li><a href="./app-shell.html">Desktop App Shell</a> (epic 13) — the epic this one was deferred out of</li><li><a href="./core-port.html">Desktop Core Port</a> (epic 12) — the app this epic distributes</li><li><a href="./../mobile/mobile-app-shell.html">Mobile App Shell</a> (epic 8), task 8.2 — the mobile equivalent this one mirrors in role, not in shape</li><li><a href="./../shared/monetization.html">Monetization</a> (epic 6), task 6.3 — a distinct, non-overlapping concern (paid-connector purchase, not app distribution) that happens to share &quot;desktop direct sale&quot; language</li></ul>',62)])])}const g=o(n,[["render",s]]);export{h as __pageData,g as default};
